// English treasure hunt (pilot: U2 + U5) for this world.
//
// Wired from world/build.js setup(): createTreasureHunt(app) returns
// { update(dt) }. All pedagogical content comes from world/hunt-data.js
// (generated by tools/gen-hunt.mjs from daughter-english-app); the steps,
// clues and targets are hand-authored in world/hunt-steps.js.
//
// No engine files are touched. Time-of-day changes use app.setTimeMode when
// the engine passes one to setup(); the current engine only exposes it on
// window.__home (assigned after setup() runs), so it is resolved lazily.

import { HUNT_UNITS } from './hunt-data.js';
import { HUNT_CHAPTERS } from './hunt-steps.js';
import { STATIONS } from './layout.js';

// Live English-app URL (Vercel), taken from the repo's About/homepage link.
export const HUNT_APP_URL = 'https://daughter-english-app.vercel.app';

const STORE_KEY = 'homecraft_hunt_progress';
const ARRIVE_DIST = 3; // metres, 2D distance to the step target
const PARTY_MS = 2600; // how long the success line stays before advancing

// ---------- Speech (adapted from daughter-english-app/src/utils/speech.js) ----------
// Pick the best natural English voice available, avoid the robotic legacy
// voices, and read at a kid-friendly rate.
const US_PREFERRED = [
  'Microsoft Jenny Online (Natural)', 'Microsoft Aria Online (Natural)',
  'Microsoft Guy Online (Natural)', 'Ava (Premium)', 'Ava (Enhanced)',
  'Samantha (Enhanced)', 'Samantha (Premium)', 'Samantha',
  'Google US English', 'Zoe (Premium)', 'Allison (Enhanced)', 'Susan', 'Victoria',
];
const ROBOTIC = ['alex', 'fred', 'albert', 'bad news', 'bahh', 'bells', 'boing',
  'bubbles', 'cellos', 'deranged', 'good news', 'hysterical', 'pipe organ',
  'trinoids', 'whisper', 'zarvox'];
let cachedVoices = [];
function refreshVoices() {
  if (!('speechSynthesis' in window)) return;
  cachedVoices = window.speechSynthesis.getVoices() || [];
}
function bestEnglishVoice() {
  const voices = cachedVoices.length ? cachedVoices : (window.speechSynthesis?.getVoices() || []);
  const en = voices.filter(v => v.lang && v.lang.toLowerCase().startsWith('en'));
  if (!en.length) return null;
  for (const name of US_PREFERRED) {
    const hit = en.find(v => v.name.toLowerCase().includes(name.toLowerCase()));
    if (hit) return hit;
  }
  const natural = en.find(v => !ROBOTIC.some(bad => v.name.toLowerCase().includes(bad)));
  return natural || en[0];
}
function speak(text) {
  try {
    if (!('speechSynthesis' in window) || !text) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.rate = 0.85;
    u.pitch = 1.0;
    const voice = bestEnglishVoice();
    if (voice) { u.voice = voice; u.lang = voice.lang; } else u.lang = 'en-US';
    window.speechSynthesis.speak(u);
  } catch { /* speech is a bonus; never break the hunt */ }
}

// ---------- Styles (world-layer only; engine/style.css is untouched) ----------
const CSS = `
#treasure-bar{position:fixed;left:50%;top:max(8px,env(safe-area-inset-top));transform:translateX(-50%);
  width:min(500px,calc(100vw - 16px));z-index:45;color:#fff;
  font:15px/1.45 -apple-system,"PingFang SC","Microsoft YaHei",sans-serif;
  background:rgba(24,32,24,.92);border:3px solid #5a4632;border-radius:14px;
  box-shadow:0 6px 24px rgba(0,0,0,.35);padding:8px 12px 10px;box-sizing:border-box}
@media (max-width:640px){#treasure-bar{top:calc(max(8px,env(safe-area-inset-top)) + 52px)}}
#treasure-bar .tb-head{display:flex;align-items:center;gap:8px}
#treasure-bar .tb-title{font-weight:700;font-size:15px;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#treasure-bar .tb-stars{font-size:14px;white-space:nowrap}
#treasure-bar button{font:inherit;cursor:pointer;border:0;border-radius:9px;padding:6px 12px;
  background:#7cb342;color:#fff;font-weight:600}
#treasure-bar button.tb-ghost{background:rgba(255,255,255,.14);font-weight:500}
#treasure-bar button.tb-collapse{background:rgba(255,255,255,.14);padding:2px 10px}
#treasure-bar .tb-progress{font-size:13px;color:#ffd54f;margin-top:4px}
#treasure-bar .tb-clue{font-size:19px;font-weight:700;margin:2px 0 6px}
#treasure-bar .tb-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
#treasure-bar .tb-hint{margin-top:6px;color:#ffe082;font-size:14px}
#treasure-bar .tb-success{margin-top:6px;font-size:16px;color:#c5e1a5}
#treasure-bar .tb-success .tb-sent{color:#fff;font-weight:600}
#treasure-bar .tb-chapters{display:flex;flex-direction:column;gap:8px;margin-top:6px}
#treasure-bar .tb-chapters button{text-align:left;background:#558b2f;padding:10px 12px}
#treasure-bar .tb-chapters button small{display:block;font-weight:400;opacity:.9}
#treasure-bar .tb-done{font-size:17px;margin-top:4px}
#treasure-bar a.tb-app{color:#ffd54f;font-weight:700}
#treasure-bar [hidden]{display:none!important}
`;

function loadStore() {
  try { return JSON.parse(localStorage.getItem(STORE_KEY)) || {}; } catch { return {}; }
}
function saveStore(data) {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(data)); } catch { /* private mode */ }
}

export function createTreasureHunt(app) {
  const player = app.player;
  const world = app.world;
  refreshVoices();
  if ('speechSynthesis' in window) window.speechSynthesis.onvoiceschanged = refreshVoices;

  const style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  const bar = document.createElement('section');
  bar.id = 'treasure-bar';
  bar.setAttribute('aria-label', 'Treasure Hunt');
  bar.innerHTML = `
    <div class="tb-head">
      <span class="tb-title">🧭 Treasure Hunt 英语寻宝</span>
      <span class="tb-stars"></span>
      <button type="button" class="tb-collapse" aria-label="收起">–</button>
    </div>
    <div class="tb-body">
      <div class="tb-pick">
        <div>选一个章节开始寻宝：</div>
        <div class="tb-chapters"></div>
        <div class="tb-resume-row" hidden>
          <button type="button" class="tb-resume"></button>
          <button type="button" class="tb-wipe tb-ghost">清除记录</button>
        </div>
      </div>
      <div class="tb-play" hidden>
        <div class="tb-progress"></div>
        <div class="tb-clue"></div>
        <div class="tb-row">
          <button type="button" class="tb-speak">🔊 朗读</button>
          <button type="button" class="tb-hintbtn tb-ghost">中文提示</button>
          <button type="button" class="tb-quit tb-ghost">换章节</button>
        </div>
        <div class="tb-hint" hidden></div>
        <div class="tb-success" hidden></div>
      </div>
      <div class="tb-done" hidden>
        <div class="tb-done-text"></div>
        <div class="tb-row" style="margin-top:8px">
          <a class="tb-app" target="_blank" rel="noopener">回到英语站做测验 →</a>
          <button type="button" class="tb-again tb-ghost">换章节</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(bar);

  const $ = sel => bar.querySelector(sel);
  const el = {
    stars: $('.tb-stars'), body: $('.tb-body'), pick: $('.tb-pick'),
    chapters: $('.tb-chapters'), resumeRow: $('.tb-resume-row'), resume: $('.tb-resume'),
    play: $('.tb-play'), progress: $('.tb-progress'), clue: $('.tb-clue'),
    hint: $('.tb-hint'), success: $('.tb-success'),
    done: $('.tb-done'), doneText: $('.tb-done-text'),
  };
  $('.tb-app').href = HUNT_APP_URL;

  let store = loadStore();
  if (typeof store.totalStars !== 'number') store.totalStars = 0;
  if (!store.done) store.done = {};

  // Hunt state. mode: 'pick' | 'play' | 'party' (celebrating) | 'done'
  let mode = 'pick';
  let chapter = null, unit = null, stepIndex = 0, chapterStars = 0;
  let targetX = 0, targetZ = 0, hasTarget = false;
  let partyUntil = 0;

  function setTimeMode(modeName) {
    // setup() app has no setTimeMode in the current engine; __home does.
    const fn = app.setTimeMode || window.__home?.setTimeMode;
    if (typeof fn === 'function') fn(modeName);
  }

  function resolveTarget(step) {
    hasTarget = false;
    if (step.station) {
      const s = STATIONS.find(s => s.id === step.station);
      if (s) { targetX = s.at[0]; targetZ = s.at[1]; hasTarget = true; }
    } else if (step.hotspot) {
      const h = world?.hotspots?.find(h => h.id === step.hotspot);
      if (h) {
        targetX = (h.box.min.x + h.box.max.x) / 2;
        targetZ = (h.box.min.z + h.box.max.z) / 2;
        hasTarget = true;
      } else if (step.fallback) { targetX = step.fallback[0]; targetZ = step.fallback[1]; hasTarget = true; }
    }
  }

  function wordOf(step) { return unit.words.find(w => w.word === step.word) || { word: step.word, translation: '' }; }
  function sentenceOf(step) { return step.sentence != null ? unit.sentences[step.sentence] : null; }

  function showStars() { el.stars.textContent = `⭐ ${store.totalStars}`; }

  function renderPicker() {
    mode = 'pick';
    el.pick.hidden = false; el.play.hidden = true; el.done.hidden = true;
    el.chapters.innerHTML = '';
    for (const ch of HUNT_CHAPTERS) {
      const u = HUNT_UNITS[ch.id];
      if (!u) continue;
      const b = document.createElement('button');
      b.type = 'button';
      b.innerHTML = `${u.story?.coverEmoji || '📖'} ${u.unit} · ${u.story ? u.story.title : u.title}` +
        `<small>${u.title} · ${ch.steps.length} 步${store.done[ch.id] ? ' · 已完成 ✅' : ''}</small>`;
      b.addEventListener('click', () => startChapter(ch.id, 0, 0));
      el.chapters.appendChild(b);
    }
    const resumable = store.chapter && HUNT_UNITS[store.chapter] && !store.done?.[store.chapter]
      && typeof store.step === 'number' && store.step > 0;
    el.resumeRow.hidden = !resumable && store.totalStars <= 0;
    if (resumable) {
      const u = HUNT_UNITS[store.chapter];
      el.resume.hidden = false;
      el.resume.textContent = `继续 ${u.unit}：第 ${store.step + 1} 步`;
      el.resume.onclick = () => startChapter(store.chapter, store.step, store.chapterStars || 0);
    } else el.resume.hidden = true;
    showStars();
  }

  function renderStep() {
    const step = chapter.steps[stepIndex];
    el.progress.textContent = `${unit.unit} 《${unit.title}》 · Step ${stepIndex + 1}/${chapter.steps.length} · ⭐ ${chapterStars}`;
    el.clue.textContent = step.clue;
    el.hint.textContent = step.hintZh;
    el.hint.hidden = true;
    el.success.hidden = true;
  }

  function startStep() {
    const step = chapter.steps[stepIndex];
    if (step.time) setTimeMode(step.time);
    resolveTarget(step);
    renderStep();
    speak(step.clue);
  }

  function startChapter(id, fromStep, fromStars) {
    chapter = HUNT_CHAPTERS.find(c => c.id === id);
    unit = HUNT_UNITS[id];
    if (!chapter || !unit) return;
    stepIndex = fromStep; chapterStars = fromStars;
    mode = 'play';
    el.pick.hidden = true; el.done.hidden = true; el.play.hidden = false;
    persist();
    startStep();
  }

  function persist() {
    store.chapter = chapter?.id || null;
    store.step = stepIndex;
    store.chapterStars = chapterStars;
    saveStore(store);
  }

  function onArrive() {
    const step = chapter.steps[stepIndex];
    const w = wordOf(step), s = sentenceOf(step);
    chapterStars += 1;
    store.totalStars += 1;
    mode = 'party';
    partyUntil = performance.now() + PARTY_MS;
    el.success.innerHTML = `Well done! ⭐ <b>${w.word}</b> ${w.translation}` +
      (s ? `<br><span class="tb-sent">${s.english}</span><br>${s.chinese}` : '');
    el.success.hidden = false;
    el.hint.hidden = true;
    showStars();
    persist();
    speak(s ? s.english : w.word);
  }

  function advance() {
    stepIndex += 1;
    if (stepIndex >= chapter.steps.length) { completeChapter(); return; }
    mode = 'play';
    persist();
    startStep();
  }

  function completeChapter() {
    mode = 'done';
    if (chapter.restoreTimeOnEnd) setTimeMode(chapter.restoreTimeOnEnd);
    store.done[chapter.id] = true;
    store.chapter = null; store.step = 0; store.chapterStars = 0;
    saveStore(store);
    el.play.hidden = true; el.pick.hidden = true; el.done.hidden = false;
    el.doneText.innerHTML = `🎉 You found all the treasures!<br>` +
      `${unit.unit} 《${unit.title}》完成，一共 ⭐ ${store.totalStars} 颗星！`;
    speak('Well done! You found all the treasures!');
  }

  $('.tb-speak').addEventListener('click', () => {
    if (chapter && mode !== 'pick') speak(chapter.steps[stepIndex].clue);
  });
  $('.tb-hintbtn').addEventListener('click', () => { el.hint.hidden = !el.hint.hidden; });
  $('.tb-quit').addEventListener('click', () => { persist(); renderPicker(); });
  $('.tb-again').addEventListener('click', renderPicker);
  $('.tb-wipe').addEventListener('click', () => {
    store = { totalStars: 0, done: {} };
    saveStore(store);
    renderPicker();
  });
  $('.tb-collapse').addEventListener('click', e => {
    const hidden = el.body.hidden = !el.body.hidden;
    e.currentTarget.textContent = hidden ? '+' : '–';
  });

  renderPicker();

  return {
    update() {
      if (!player?.pos) return;
      if (mode === 'play' && hasTarget) {
        const dx = player.pos.x - targetX, dz = player.pos.z - targetZ;
        if (dx * dx + dz * dz <= ARRIVE_DIST * ARRIVE_DIST) onArrive();
      } else if (mode === 'party' && performance.now() >= partyUntil) {
        advance();
      }
    },
  };
}
